        ["Jendela kamera dengan tombol cermin dan putar"] = "Camera window with mirror and rotate buttons",
        ["Kuota Claude dan Codex serta kinerja PC."] = "Claude and Codex quota plus PC performance.",
        ["Tanpa login terminal, angkanya dari catatan aplikasi Claude Desktop"] = "No terminal login needed; the numbers come from the Claude Desktop app's records",
        ["Kalender, hari libur, jadwal sholat, dan adzan."] = "Calendar, holidays, prayer times and adhan.",
        ["Tautan dari Google Calendar, Outlook, dan sejenisnya"] = "Link from Google Calendar, Outlook and similar",
