        ["Tangkap layar, clipboard, Discord, dan Meet."] = "Screenshots, clipboard, Discord and Meet.",
        ["Discord dan Meet"] = "Discord and Meet", ["Cara cepat siap; cara lengkap belum disambungkan"] = "Quick way ready; full way not connected yet",
