        ["Tidak ada yang diunduh otomatis; unduh hanya bila fiturnya dibutuhkan"] = "Nothing downloads automatically; download only when you need the feature",
        ["Untuk tombol mikrofon di tab Musik: 12 detik suara PC dikirim ke api.audd.io hanya saat ditekan"] = "For the microphone button in the Music tab: 12 seconds of PC audio are sent to api.audd.io only when pressed",
        ["Pintasan Discord: mic"] = "Discord shortcut: mic", ["Pintasan Discord: deafen"] = "Discord shortcut: deafen",
        ["Pintasan Meet: mic"] = "Meet shortcut: mic", ["Pintasan Meet: kamera"] = "Meet shortcut: camera",
