        ["Pintasan Aksi cepat"] = "Quick action shortcut", ["Kolom ketik perintah singkat: t 10m, fokus 25, catat beli susu, w link, minum 250, tema neon. Mis. ctrl+alt+k; kosongkan untuk mematikan"] = "A box for short commands: t 10m, fokus 25, catat buy milk, w link, minum 250, tema neon. E.g. ctrl+alt+k; leave empty to turn off",
        ["t 10m  ·  fokus 25  ·  catat beli susu  ·  w <link>  ·  minum 250  ·  tema neon  ·  = 12*5  ·  5 km mi  ·  buka monitor  ·  perf  ·  bt  ·  sembunyi  ·  kunci  ·  tidur  ·  gelap  ·  terang  ·  wifi off  ·  bluetooth on"] = "t 10m  ·  fokus 25  ·  catat buy milk  ·  w <link>  ·  minum 250  ·  tema neon  ·  = 12*5  ·  5 km mi  ·  open monitor  ·  perf  ·  bt  ·  hide  ·  lock  ·  sleep  ·  dark  ·  light  ·  wifi off  ·  bluetooth on",
        ["Kilat tepi saat lagu ganti"] = "Edge flash on track change", ["Tepi pill menyala sekali dengan warna sampul. Hanya di island, tidak di layar penuh"] = "The pill edge glows once in the cover colour. Island only, not in fullscreen",
        ["Rekap lagu dan artis teratas"] = "Top songs and artists recap", ["Mencatat lagu yang kamu dengarkan sedikitnya 30 detik, hanya di PC ini (playlog.tsv). Dilihat lewat tombol Rekap di tab Musik"] = "Logs songs you listen to for at least 30 seconds, on this PC only (playlog.tsv). View it with the Recap button in the Music tab",
        ["Hapus catatan rekap"] = "Delete recap log", ["Hapus"] = "Delete", ["Rekap"] = "Recap", ["Rekap 7 hari terakhir"] = "Last 7 days", ["Rekap 30 hari terakhir"] = "Last 30 days", ["30 hari"] = "30 days", ["7 hari"] = "7 days", ["Kembali"] = "Back", ["Lagu teratas"] = "Top songs", ["Artis teratas"] = "Top artists",
        ["Belum ada rekap. Lagu yang kamu dengarkan sedikitnya 30 detik dicatat di sini (hanya di PC ini)."] = "No recap yet. Songs you listen to for at least 30 seconds are logged here (on this PC only).", ["Rekap dimatikan di Pengaturan > Musik."] = "Recap is turned off in Settings > Music.",
        ["Hemat baterai otomatis"] = "Automatic battery saver", ["Saat memakai baterai dan sisanya di bawah angka ini, pembaruan cepat dikurangi (karaoke lirik, tab Monitor). 0 = mati"] = "On battery and below this level, fast updates are reduced (karaoke lyrics, Monitor tab). 0 = off",
        ["Kehalusan animasi"] = "Animation smoothness", ["Otomatis: animasi latar 30 fps, buka/tutup/ganti tab 60 fps. Penuh: semua 60 fps. Berlaku setelah ZaxLet dimulai ulang"] = "Auto: background animations 30 fps, open/close/tab switch 60 fps. Full: everything 60 fps. Applies after restarting ZaxLet", ["Penuh (60 fps)"] = "Full (60 fps)",
